// 2. 自定义限流KeyResolver
@Bean
public KeyResolver userKeyResolver() {
    return exchange -> {
        // 按用户ID限流
        String userId = exchange.getRequest()
            .getHeaders().getFirst("X-User-Id");
        if (userId != null) {
            return Mono.just(userId);
        }
        // 降级为IP限流
        String ip = exchange.getRequest()
            .getRemoteAddress().getAddress().getHostAddress();
        return Mono.just(ip);
    };
}

// 3. JWT鉴权过滤器
@Component
public class AuthFilter implements GlobalFilter, Ordered {
    @Autowired
    private JwtUtil jwtUtil;

    @Override
    public Mono<Void> filter(ServerWebExchange exchange,
            GatewayFilterChain chain) {
        String path = exchange.getRequest().getPath().value();
        // 白名单放行
        if (isWhitelist(path)) {
            return chain.filter(exchange);
        }

        String token = exchange.getRequest()
            .getHeaders().getFirst("Authorization");
        if (token == null || !token.startsWith("Bearer ")) {
            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
            return exchange.getResponse().setComplete();
        }

        try {
            Claims claims = jwtUtil.parseToken(token.substring(7));
            // 将用户信息透传给后端服务
            ServerHttpRequest request = exchange.getRequest()
                .mutate()
                .header("X-User-Id", claims.getSubject())
                .header("X-User-Role", claims.get("role", String.class))
                .build();
            return chain.filter(exchange.mutate().request(request).build());
        } catch (Exception e) {
            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
            return exchange.getResponse().setComplete();
        }
    }

    @Override
    public int getOrder() {
        return -100; // 最高优先级
    }
}

// 4. 灰度发布过滤器
@Component
public class GrayReleaseFilter implements GlobalFilter, Ordered {
    @Autowired
    private GrayRuleConfig grayRuleConfig;

    @Override
    public Mono<Void> filter(ServerWebExchange exchange,
            GatewayFilterChain chain) {
        String userId = exchange.getRequest()
            .getHeaders().getFirst("X-User-Id");

        // 基于用户ID灰度
        if (grayRuleConfig.getGrayUsers().contains(userId)) {
            ServerHttpRequest request = exchange.getRequest()
                .mutate()
                .header("X-Gray", "true")
                .build();
            return chain.filter(exchange.mutate().request(request).build());
        }

        // 基于比例灰度
        if (Math.abs(userId.hashCode()) % 100
                < grayRuleConfig.getGrayPercent()) {
            ServerHttpRequest request = exchange.getRequest()
                .mutate()
                .header("X-Gray", "true")
                .build();
            return chain.filter(exchange.mutate().request(request).build());
        }

        return chain.filter(exchange);
    }

    @Override
    public int getOrder() {
        return -50;
    }
}
